def sortString(s: str) -> str:
    # Count frequency of each character (26 lowercase English letters)
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1

    n = len(s)
    result = []

    while len(result) < n:
        # Increasing: from 'a' to 'z'
        for i in range(26):
            if count[i] > 0:
                result.append(chr(i + ord('a')))
                count[i] -= 1
        # Decreasing: from 'z' to 'a'
        for i in range(25, -1, -1):
            if count[i] > 0:
                result.append(chr(i + ord('a')))
                count[i] -= 1

    return ''.join(result)
